import os
import re
from typing import Any, Dict, List, Literal, Optional

import requests


OPENAI_API_KEY = os.environ["OPENAI_API_KEY"]
OPENAI_API_URL = "https://api.openai.com/v1/responses"
MODEL = "gpt-4.1-mini"


UnsafeAction = Literal["flag", "redact"]


def _extract_json_object(text: str) -> Dict[str, Any]:
    text = text.strip()
    if text.startswith("{") and text.endswith("}"):
        return requests.models.complexjson.loads(text)

    match = re.search(r"\{.*\}", text, flags=re.DOTALL)
    if not match:
        raise ValueError("No JSON object found in model response")
    return requests.models.complexjson.loads(match.group(0))


def _normalize_spans(spans: List[Dict[str, Any]], text: str) -> List[Dict[str, Any]]:
    normalized = []
    n = len(text)

    for span in spans:
        start = span.get("start")
        end = span.get("end")
        category = str(span.get("category", "unsafe"))
        reason = str(span.get("reason", "")).strip()

        if not isinstance(start, int) or not isinstance(end, int):
            continue
        start = max(0, min(start, n))
        end = max(0, min(end, n))
        if end <= start:
            continue

        normalized.append(
            {
                "start": start,
                "end": end,
                "text": text[start:end],
                "category": category,
                "reason": reason,
            }
        )

    normalized.sort(key=lambda s: (s["start"], s["end"]))

    merged: List[Dict[str, Any]] = []
    for span in normalized:
        if not merged or span["start"] > merged[-1]["end"]:
            merged.append(span)
        else:
            prev = merged[-1]
            prev["end"] = max(prev["end"], span["end"])
            prev["text"] = text[prev["start"]:prev["end"]]
            if span["category"] not in prev["category"]:
                prev["category"] = f'{prev["category"]},{span["category"]}'
            if span["reason"]:
                prev["reason"] = (prev["reason"] + "; " + span["reason"]).strip("; ")

    return merged


def _redact_text(text: str, spans: List[Dict[str, Any]], replacement: str = "[REDACTED]") -> str:
    if not spans:
        return text

    parts = []
    last = 0
    for span in spans:
        parts.append(text[last:span["start"]])
        parts.append(replacement)
        last = span["end"]
    parts.append(text[last:])
    return "".join(parts)


def moderate_text_content(
    text: str,
    action: UnsafeAction = "flag",
    replacement: str = "[REDACTED]",
    timeout: int = 30,
) -> Dict[str, Any]:
    system_prompt = (
        "You are a text safety tagging system. "
        "Identify unsafe spans in the user's text that should be flagged or redacted. "
        "Unsafe includes credible threats, instructions for violent wrongdoing, self-harm encouragement, "
        "sexual content involving minors, explicit personal data exposure, hateful slurs used abusively, "
        "and illegal hard-drug manufacturing instructions. "
        "Return ONLY strict JSON with this exact schema: "
        '{"unsafe": boolean, "spans": [{"start": int, "end": int, "category": string, "reason": string}]}. '
        "Indexes must be 0-based Python string offsets into the original text. "
        "If there are no unsafe spans, return unsafe=false and spans=[]."
    )

    payload = {
        "model": MODEL,
        "input": [
            {"role": "system", "content": system_prompt},
            {"role": "user", "content": text},
        ],
        "temperature": 0,
    }

    headers = {
        "Authorization": f"Bearer {OPENAI_API_KEY}",
        "Content-Type": "application/json",
    }

    response = requests.post(OPENAI_API_URL, headers=headers, json=payload, timeout=timeout)
    response.raise_for_status()
    data = response.json()

    output_text = data.get("output_text")
    if not output_text:
        fragments = []
        for item in data.get("output", []):
            for content in item.get("content", []):
                if content.get("type") == "output_text":
                    fragments.append(content.get("text", ""))
        output_text = "".join(fragments)

    parsed = _extract_json_object(output_text)
    spans = _normalize_spans(parsed.get("spans", []), text)
    unsafe = bool(parsed.get("unsafe")) or bool(spans)

    result: Dict[str, Any] = {
        "unsafe": unsafe,
        "spans": spans,
    }

    if action == "redact":
        result["redacted_text"] = _redact_text(text, spans, replacement=replacement)

    return result
